public class DatabaseConnectionPool {
    // volatile ensures visibility across threads
    private static volatile DatabaseConnectionPool instance;

    private DatabaseConnectionPool() {} // private constructor

    public static DatabaseConnectionPool getInstance() {
        if (instance == null) {
            synchronized (DatabaseConnectionPool.class) {
                if (instance == null) { // double-checked
                    instance = new DatabaseConnectionPool();
                }
            }
        }
        return instance;
    }
}

// Simplest Java Singleton: use enum
public enum AppConfig {
    INSTANCE;
    public String getDbUrl() { return "jdbc:mysql://localhost/app"; }
}

// Spring creates ONE instance of UserService and reuses it everywhere
@Service
public class UserService {
    // IMPORTANT: Do not store request-specific state here!
    // Instance variables are shared across all requests
    // private User currentUser; // WRONG - race condition!

    public User getUser(Long id) {
        // method-local variables are safe
        return userRepository.findById(id).orElseThrow();
    }
}

// Other scopes
@Scope("prototype") // new instance each time
@Scope("request")  // new instance per HTTP request

public enum DatabaseConfig {
    INSTANCE;

    private final String url = "jdbc:mysql://localhost/app";
    private final String username = "root";

    public String getUrl() { return url; }
    public String getUsername() { return username; }
}

// Usage
String dbUrl = DatabaseConfig.INSTANCE.getUrl();

